// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val, uint256 _val2, address _log2) internal {
        try c.SetMinSum(_val) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool r1;
        bool r2;
        try c.SetMinSum(_val2) { r1 = false; } catch { r1 = true; }
        try c.SetLogFile(_log2) { r2 = false; } catch { r2 = true; }
        assertTrue(r1 && r2 && c.MinSum() == _val);
    }

    function testFuzz_run(uint256 _val, uint256 _val2, address _log2) public {
        vm.assume(_log2.code.length == 0 && uint160(_log2) > 0xffff && _log2 != address(this) && _log2 != address(c) && _log2 != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _log2 != 0x000000000000000000636F6e736F6c652e6c6f67 && _log2 != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _log2 != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_val, _val2, _log2);
    }

    receive() external payable {}
}
